window.WIKI.find(t=>t.id==='plasticity').body=window.WIKI.find(t=>t.id==='plasticity').body.replace('<h2>מה רואים בהדמיה?</h2>','<h2>דוגמה היסטורית לשינוי בקשר</h2><p>בליס ולומו פרסמו ב־1973 הדגמה של הגברה מתמשכת בתגובה סינפטית באזור ההיפוקמפוס של ארנבים לאחר גירוי חוזר. תופעה זו, המכונה פוטנציאציה ארוכת טווח (LTP), נעשתה מודל מרכזי לחקר פלסטיות סינפטית. היא דוגמה למנגנון מסוים, ולא הגדרה של כל סוגי הלמידה.</p><h2>מה רואים בהדמיה?</h2>');
